"""Generate verification/VCRM.md from the level files.

Usage: python tools/vcrm.py [--root DIR] [--out FILE] [--check]
--check does not write; it exits 1 if any requirement lacks a verification method.
"""
import argparse
import sys
from pathlib import Path

import reqlib
from reqlib import Finding

METHODS = ["Inspection", "Analysis", "Demonstration", "Test"]
HEADER = ("# Verification cross-reference matrix\n\n"
          "_Generated by tools/vcrm.py from the level files. Do not edit by hand._\n\n")
COLUMNS = ["ID", "Level", "Type", "Method", "Procedure", "Success criteria", "Status"]


def cell(text):
    return (text or "").replace("|", "\\|").replace("\n", " ")


def rows(repo):
    out = []
    for r in repo.records:
        if r.get("Status") == "Deleted":
            continue
        method, proc, crit = reqlib.split_verification(r.get("Verification"))
        out.append((r, [r.id, r.get("Level"), r.get("Type"), method, proc, crit, r.get("Status")]))
    return out


def render(repo):
    data = rows(repo)
    if not data:
        return HEADER + "_No requirements yet._\n"
    lines = ["| " + " | ".join(COLUMNS) + " |", "| " + " | ".join("---" for _ in COLUMNS) + " |"]
    for _, row in data:
        lines.append("| " + " | ".join(cell(c) for c in row) + " |")
    return HEADER + "\n".join(lines) + "\n"


def missing_methods(repo):
    return [Finding(str(r.file), r.where("Verification"), "error", "NO-VERIFICATION", r.id,
                    "no verification method (Inspection/Analysis/Demonstration/Test)")
            for r, row in rows(repo) if row[3] not in METHODS]


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--root", type=Path, default=reqlib.REPO_ROOT)
    ap.add_argument("--out", type=Path, help="output file (default: <root>/verification/VCRM.md)")
    ap.add_argument("--check", action="store_true", help="check only; do not write")
    args = ap.parse_args(argv)
    repo = reqlib.load_repo(args.root)
    if args.check:
        return reqlib.report(repo.problems + missing_methods(repo))
    out = args.out or Path(args.root) / "verification" / "VCRM.md"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render(repo), encoding="utf-8", newline="\n")
    print(f"wrote {out} ({len(rows(repo))} requirement(s))")
    return reqlib.report(repo.problems)


if __name__ == "__main__":
    sys.exit(main())
